try:
    print('>>> f = delattr')
    print('>>> x = type(1)')
    print('>>> y = range(0)')
    print('>>> f(x, y)')
    f = delattr
    x = type(1)
    y = range(0)
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
